from pathlib import Path
import json,hashlib,pandas as pd,numpy as np
R=Path(__file__).resolve().parents[2];OUT=R/'maps/cycle07_actual060_preview_binding_v3';assert not OUT.exists();OUT.mkdir(parents=True)
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def spec(p):return {'path':str(p.resolve()),'sha256':sha(p)}
N=R/'typology/cycle07_complete/normalized_primary_v3/cap060_supported_end_forest';T=R/'typology/cycle07_complete/classified_primary_v3/cap060_supported_end_forest';BASE=R/'model/output_cycle06_access_v2_source_geography_inclusive/nodes.parquet';u=pd.read_parquet(N/'normalized_units.parquet');ty=pd.read_parquet(T/'complete_typology.parquet');members=pd.read_parquet(N/'memberships_scoped.parquet');vid=u.operational_view_id.iloc[0];cols=['id','name','lat','lon','population_2021','source_record_id_2021','source2021_effective_settlement_type','source2021_role_has_dated_source','is_additive_source_unit'];n=pd.read_parquet(BASE,columns=cols);n['formal_city2021']=n.source2021_effective_settlement_type.eq('город')&n.source2021_role_has_dated_source.eq(True)&n.source_record_id_2021.notna()&n.is_additive_source_unit.eq(True);n=n[cols[:6]+['formal_city2021']]
uc=['unit_id','core_id','kind','unit_role','name','lat','lon','candidate_cap','partition_role','operational_view_id','display_retained','empirical_resolution_supported','center_scope','n_children','ancestry_depth','max_member_direct_minutes','extent_complete','n_member_direct_unknown','primary2010_population_share','protected_secondary2010_population_share','population2010_known_denominator','2010_missing_population_count','population_quality_share_denominator_scope']+[f'unknown_nonadditive_metropolitan_{label}_population_slots_{year}' for year in [2002,2010,2021] for label in ['all','focal','nonfocal']];projection=u[uc].copy();projection['level']=str(vid);sources={}
for name,d in [('nodes',n),('units',projection),('memberships',members),('types',ty)]:
 p=OUT/(name+'.parquet');d.to_parquet(p,index=False,compression='zstd');sources[name]=spec(p)
for key,p in [('raw_normalized_units',N/'normalized_units.parquet'),('raw_type_receipt',T/'receipt.json'),('source_population353_view',R/'typology/cycle07_complete/population_source353_v1/effective_population_source_view.parquet')]:sources[key]=spec(p)
coast=R/'maps/sources/ne_110m_coastline.geojson'
if coast.exists():sources['coastline']=spec(coast)
admissions=[]
for p in [R/'reviews/cycle07_baseline_units_independent/audit.json',R/'reviews/cycle07_normalization_v3_independent/cap060/audit.json',R/'reviews/cycle07_typology_independent/cap060_v3/audit.json']:
 j=json.load(open(p));assert j['all_checks_passed'];admissions.append(dict(spec(p),status_pointer=['status'],expected_status=j['status']))
c={'family':'cycle07_bottomup','status':'ACTUAL060_PREVIEW_ONLY_NOT_ALL5_ALL50_ATLAS','retained_resolutions':[str(vid)],'zoom_resolution':str(vid),'view_metadata':{str(vid):{'label':'Проверка прежнего допустимого ядра: дорожный охват60 мин','kind':'operational_forest'}},'external_context_anchor_ids':['ctx:RU-FED-MOW','ctx:RU-FED-SPB'],'dpi':125,'sources':sources,'independent_admissions':admissions,'component_integration_status':{'population2010':'353 новых подтверждения включены','functions_routes_coordinates':'Старый кадр q7. 477 координат приняты отдельно, здесь ещё не включены.','status':'Прежнее правило геометрически допустимого ядра. Не итоговые агломерации/географические ступени; новый доминантный центр требует отдельного расчёта.'},'population_frame_scope':{'full_source_view_rows':173864,'ordinary_NP_partition_rows':173856,'context_partition_rows':2,'geographic_partition_rows':173858,'excluded_nonadditive_source_rows':6},'structural_display_aliases':{'protected_carry':'Отдельный НП / присоединение не подтверждено','rural_zone':'Система с сельским окружением','local_without_rural_zone':'Система без сельского окружения','rural_composition_unknown':'Состав окружения не установлен'}}
(OUT/'map_config.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n');assert len(members)==173858 and len(u)==28501 and len(ty)==28501 and set(members.unit_id)==set(u.unit_id)==set(ty.unit_id);proof={'status':'ACTUAL060_PROJECTION_COMPUTED_PENDING_INDEPENDENT_BINDING_REVIEW','all_projected_source_fields_preserved':True,'scientific_type_changed':False,'coordinate_changed':False,'derived_level_is_operational_view_id_not_empirical_rank':True,'actual_full_atlas':False,'n_units':len(u),'n_members':len(members),'source_base_nodes':spec(BASE),'source_normalized_units':spec(N/'normalized_units.parquet'),'source_types':spec(T/'complete_typology.parquet'),'source_memberships':spec(N/'memberships_scoped.parquet'),'files':{p.name:sha(p) for p in OUT.iterdir() if p.is_file()},'code_sha256':sha(__file__)};(OUT/'binding_receipt.json').write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n');print(OUT)
